// Sparkle Valley's illustrated icons for menus: drawn pictures in the game's own style (chunky shapes,
// soft dark outline) instead of phone emoji, and each one moves a little in a way that fits it: clock hands
// turn, a kite floats, a flame flickers, a puppy's tail wags, bubbles rise, a train puffs.
//   pic('🕒')  → the clock picture (or the emoji itself if there is no picture for it yet)
// The animations are CSS (css/style.css, .art .a-*), and stop when "calm mode" or reduced motion is on.
const O = '#3b2a4f', W = `stroke="${O}" stroke-width="2.6" stroke-linejoin="round" stroke-linecap="round"`, N = 'fill="none"';
const svg = (body, cls = '') => `<svg class="art ${cls}" viewBox="0 0 48 48" aria-hidden="true">${body}</svg>`;
const g = (cls, body, o = '24px 24px') => `<g class="${cls}" style="transform-origin:${o}">${body}</g>`;
const circ = (x, y, r, f, extra = '') => `<circle cx="${x}" cy="${y}" r="${r}" fill="${f}" ${W} ${extra}/>`;
const dot = (x, y, r = 1.8, f = O) => `<circle cx="${x}" cy="${y}" r="${r}" fill="${f}"/>`;
const eyes = (x1, x2, y, r = 1.8) => `<g class="a-blink" style="transform-origin:24px ${y}px">${dot(x1, y, r)}${dot(x2, y, r)}</g>`;
const smile = (x, y, w = 6) => `<path d="M${x - w / 2} ${y}q${w / 2} ${w / 2.2} ${w} 0" ${W} ${N}/>`;
const star5 = (cx, cy, r, f) => { let d = ''; for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, k = i % 2 ? r * .45 : r; d += (i ? 'L' : 'M') + (cx + Math.cos(a) * k).toFixed(1) + ' ' + (cy + Math.sin(a) * k).toFixed(1); } return `<path d="${d}z" fill="${f}" ${W}/>`; };
const sparkle = (x, y, s = 1, f = '#fff6b0') => `<path d="M${x} ${y - 4 * s}l${s} ${3 * s} ${3 * s} ${s}-${3 * s} ${s}-${s} ${3 * s}-${s}-${3 * s}-${3 * s}-${s} ${3 * s}-${s}z" fill="${f}" stroke="${O}" stroke-width="1.2" stroke-linejoin="round"/>`;

const ART = {};
const def = (keys: string, body: string, cls = '') => { for (const k of keys.split(' ')) ART[k] = svg(body, cls); };

// Hand-drawn tools for the folk-game rhythm and Fruit Parade picture choices.
def('🪚', `<path d="M16 12l27 6-3 5-4-1-2 5-4-1-2 5-4-1-3 5-9-8z" fill="#bfe3f2" ${W}/><path d="M7 9l12 4-6 17-9-5z" fill="#ffb347" ${W}/><path d="M9 16l4 1-2 6-4-2z" fill="#fff6d8" ${W}/><path d="M23 17l12 3" stroke="#fff" stroke-width="2" stroke-linecap="round"/>`);
def('🗝️', `${circ(15, 14, 10, '#ffd23f')}${circ(15, 14, 4, '#fff6d8')}<path d="M21 22l19 18-5 4-5-5 3-3-5-4-3 3-6-6z" fill="#ffd23f" ${W}/>`);

