def('🎒', `<path d="M15 15c0-6 4-9 9-9s9 3 9 9" ${N} ${W}/>` + g('a-wiggle', `<rect x="8" y="14" width="32" height="28" rx="10" fill="#ffb347" ${W}/><rect x="15" y="27" width="18" height="10" rx="4" fill="#ffd27a" ${W}/><path d="M24 27v4" ${W}/>`, '24px 42px'));
